examples:
import type { EmojiData, EmojiItem } from "@kitora/pickers/core"

// One row per emoji, as a full data set publishes it (adapt the field names to yours).
interface Row {
  readonly emoji: string
  readonly name: string
  readonly group: string
  readonly keywords: readonly string[]
  readonly skins?: readonly string[]
}

export function toEmojiData(rows: readonly Row[]): EmojiData {
  const groups = new Map<string, EmojiItem[]>()
  for (const { emoji, name, group, keywords, skins } of rows) {
    const item: EmojiItem = skins ? { emoji, name, keywords, skins } : { emoji, name, keywords }
    groups.set(group, [...(groups.get(group) ?? []), item])
  }
  return [...groups].map(([group, emojis]) => ({ id: group, label: group, emojis }))
}

props.description:
The field: `segments` (default) or `text` (formats plus natural language, previewed before Enter or blur commits).
`text` works for a single date-time too ("15 dec 3:30 pm", "tomorrow at 9", the locale's own 12- or 24-hour time);
a range or the time modes with a time keep the segments.

